<?php $pageTitle='Live Score';require_once __DIR__.'/includes/header.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=$pdo->prepare("SELECT m.*,p1.name p1_name,p1.logo p1_logo,p2.name p2_name,p2.logo p2_logo FROM matches m LEFT JOIN participants p1 ON p1.id=m.participant1_id LEFT JOIN participants p2 ON p2.id=m.participant2_id WHERE m.id=?");$s->execute([$id]);$m=$s->fetch();if(!$m){http_response_code(404);echo '<main class="container empty"><h2>Match not found</h2></main>';require __DIR__.'/includes/footer.php';exit;}$ev=$pdo->prepare("SELECT me.*,p.name participant_name FROM match_events me LEFT JOIN participants p ON p.id=me.participant_id WHERE me.match_id=? ORDER BY me.created_at DESC LIMIT 30");$ev->execute([$id]);?>
<main><section class="page-hero"><div class="container"><div class="eyebrow"><?=e($m['round'])?> · Match #<?=$m['id']?></div><h1>Live scoreboard</h1></div></section><section class="section"><div class="container"><div class="card scoreboard" id="public-scoreboard"><div><div class="team-logo"><?=strtoupper(substr($m['p1_name']??'T',0,1))?></div><h2 id="public-team1"><?=e($m['p1_name']??'TBD')?></h2></div><div><div class="scoreboard-score"><strong id="public-score1"><?=str_pad((string)$m['score1'],2,'0',STR_PAD_LEFT)?></strong><span>VS</span><strong id="public-score2"><?=str_pad((string)$m['score2'],2,'0',STR_PAD_LEFT)?></strong></div><span id="public-status" class="badge <?=e($m['status'])?>"><?=e($m['status'])?></span></div><div><div class="team-logo"><?=strtoupper(substr($m['p2_name']??'T',0,1))?></div><h2 id="public-team2"><?=e($m['p2_name']??'TBD')?></h2></div></div><div class="match-info"><div><small>Round</small><strong><?=e($m['round'])?></strong></div><div><small>Court / Arena</small><strong><?=e($m['court']??'TBA')?></strong></div><div><small>Match Timer</small><strong id="match-timer">00:00:00</strong></div><div><small>Last update</small><strong id="public-updated"><?=date('H:i:s',strtotime($m['updated_at']))?></strong></div></div><div class="section-head" style="margin-top:35px"><div><div class="eyebrow">Score log</div><h2>Match history</h2></div></div><div class="card timeline" id="event-timeline"><?php $events=$ev->fetchAll();if(!$events):?><div class="empty">No match events yet.</div><?php endif;foreach($events as $e):?><div class="event"><time><?=date('H:i:s',strtotime($e['created_at']))?></time><p><strong><?=e($e['participant_name']??ucfirst($e['event_type']))?></strong><br><?= $e['event_type']==='score'?($e['score_change']>0?'+':'').$e['score_change'].' Point':ucfirst($e['event_type'])?></p></div><?php endforeach;?></div></div></section></main>
<script>const matchStarted=<?=json_encode($m['started_at'])?>;async function refreshMatch(){try{const {data:m}=await api(`${APP_BASE}/api/get_match.php?id=<?=$id?>`);document.querySelector('#public-score1').textContent=String(m.score1).padStart(2,'0');document.querySelector('#public-score2').textContent=String(m.score2).padStart(2,'0');document.querySelector('#public-status').textContent=m.status.toUpperCase();document.querySelector('#public-status').className=`badge ${m.status}`;document.querySelector('#public-updated').textContent=new Date(m.updated_at.replace(' ','T')).toLocaleTimeString('id-ID')}catch(e){}}function timer(){if(!matchStarted)return;const seconds=Math.max(0,Math.floor((Date.now()-new Date(matchStarted.replace(' ','T')).getTime())/1000));document.querySelector('#match-timer').textContent=[Math.floor(seconds/3600),Math.floor(seconds%3600/60),seconds%60].map(n=>String(n).padStart(2,'0')).join(':')}setInterval(refreshMatch,3000);setInterval(timer,1000);timer()</script>
<?php require __DIR__.'/includes/footer.php';?>
